from lib import *
S = SS('s29')
steps = [
    step("Selector 来自 parsel 1.12.1,解析和查询的底层是 lxml 6.1.3(libxml2 2.14.6);css() 不是独立引擎,而是先用 cssselect 1.6.0 翻译成 XPath 再交给 lxml:div.item > a 变成 descendant-or-self::div[@class and contains(@class, 'item') and contains(concat(' ', normalize-space(@class), ' '), ' item ')]/a;li:first-child 变成 count(preceding-sibling::*) = 0;::text 变成 /text(),::attr(href) 变成 /@href。类选择器翻译出来的 XPath 很长。", t=tl(S(1)), mark=lidx(S(1), 'div.item > a', 'li:first-child', 'p::text', 'a::attr(href)'), done=lidx(S(1), 'parsel 1.12.1'), kv=KV([['解析', 'lxml / libxml2 2.14.6'], ['css()', '先翻译成 XPath(cssselect)'], ['类选择器', 'contains(concat(…normalize-space(@class)…))'], ['::text / ::attr()', '翻译成 /text() 和 /@属性']], ['css()'])),
    step("文本取法的差别(<div id=a>head <b>bold</b> tail <i>it</i></div>):div::text 和 //div/text() 只取直接子文本 ['head ', ' tail '];div ::text(带空格)和 //div//text() 取所有后代文本 ['head ', 'bold', ' tail ', 'it'];string(//div) 把所有后代文本拼成一个 'head bold tail it'。.get() 在没有匹配时返回 None,.get(default='N/A') 返回 N/A,.getall() 返回 [];re() 对节点的 HTML 文本做正则,re_first 找不到时可以给 default。", t=tl(S(2)), mark=lidx(S(2), 'div ::text', '//div//text()', 'string(//div)'), done=lidx(S(2), 'div::text', '//div/text()', '不存在时', 're / re_first'), kv=KV([['div::text', '只取直接子文本节点'], ['div ::text / //div//text()', '所有后代文本节点'], ['string(//div)', '拼成一个字符串'], ['没匹配', 'get() = None,getall() = []']], ['div::text'])),
    step("HTML 容错交给 libxml2:<p>one<p>two<table><tr><td>a<td>b</table><b><i>x</b></i>&unknown; &amp; <div 修复成 <p>one</p><p>two</p><table><tr><td>a</td><td>b</td></tr></table><b><i>x</i></b>&amp;unknown; &amp; ——未关闭的 p 和 td 补上,交叉的 b/i 被理顺,未知实体 &unknown; 变成 &amp;unknown;,结尾残缺的 <div 被丢掉。type='xml' 也不会因为格式错误抛异常(recover 模式),但修出来的结构完全不同(p 嵌套 p、td 嵌套 td、<div/>);空文档 Selector(text='') 的 root 是 <html> 元素,get() 返回 '<html></html>'。", t=tl(S(3)), mark=lidx(S(3), 'type="xml" 也不抛错', '空文档'), done=lidx(S(3), 'lxml 修复后'), kv=KV([['HTML 解析器', '补全未关闭标签、理顺交叉标签'], ['未知实体 / 残缺标签', '&amp;unknown; / 丢弃'], ['type="xml"', 'recover 模式,不抛错但结构不同'], ['空文档', 'root = <html>']], ['HTML 解析器'])),
    step("XML 命名空间:Atom 文档带默认命名空间时 //entry 一个都查不到(0 个);用 namespaces={'a': 'http://www.w3.org/2005/Atom'} 加前缀 //a:entry 查到 2 个;或者先 remove_namespaces(),//entry 查到 2 个,//link/@href 得到 ['/a', '/b']。", t=tl(S(4)), mark=lidx(S(4), '//entry   '), done=lidx(S(4), '//a:entry', 'remove_namespaces'), kv=KV([['默认命名空间', '//entry 查不到(0 个)'], ['带前缀', '//a:entry 查到 2 个'], ['remove_namespaces()', '去掉后 //entry 查到 2 个']], ['默认命名空间'])),
    step("约 1 MB、20,000 个 li 的文档:解析 Selector(text=html) 约 15.8 ms;同一个 Selector 上取 20,000 个 href——css('li.item a::attr(href)') 178.0 ms,等价的 xpath(\"//li[@class='item']/a/@href\") 只要 28.9 ms(6 倍),//a/@href 23.5 ms;css('li:nth-child(100)') 要 1203.4 ms,因为它翻译成 count(preceding-sibling::*) = 99,对 20,000 个兄弟节点逐个数前面的兄弟,是平方级。css('li') 只构造 20,000 个 Selector 对象就要 16.9 ms,re() 对整个文档做正则 10.2 ms。HtmlResponse.css 第一次含解析 53.7 ms,同一个 response 第二次起 37.9 ms(response.selector 缓存了解析结果)。", t=tl(S(5)), mark=lidx(S(5), 'nth-child(100)', 'li.item a::attr'), done=lidx(S(5), 'xpath', '解析', 'HtmlResponse.css'), b=bars([['xpath 取 href', 28.9, '28.9 ms'], ['css 类选择器取 href', 178.0, '178.0 ms'], ['css nth-child(100)', 1203.4, '1203.4 ms']], 1203.4, mark=[2], done=[0, 1]), kv=KV([['解析 1 MB', '15.8 ms'], ['xpath @class="item"', '28.9 ms'], ['css li.item', '178.0 ms(6 倍)'], ['css :nth-child(100)', '1203.4 ms(平方级)']], ['css :nth-child(100)'])),
]
A = mkarts('s29', 29, 'Scrapy,Selector,parsel,xpath,css,lxml,真实验证,动画演示',
    '实测 Selector 的底层:parsel 1.12.1 + lxml 6.1.3(libxml2 2.14.6),css 先被 cssselect 翻译成 XPath;::text 与 //text()、string() 取文本的差别;libxml2 对坏 HTML 的修复;XML 命名空间要 remove_namespaces;1 MB 文档上 xpath 取 href 28.9 ms、等价 css 178.0 ms、css :nth-child(100) 1203.4 ms。',
    'response.css() 和 response.xpath() 到底谁在执行?::text 与 //text() 差在哪?坏掉的 HTML 被修成什么样?为什么有些 css 选择器特别慢?这篇从翻译后的 XPath 讲起,再量一遍 1 MB 文档上的耗时。',
    [('6 倍', '1 MB 文档上等价的 css(178.0 ms)比 xpath(28.9 ms)取 href 慢的倍数'), ('1203.4 ms', 'css("li:nth-child(100)") 在 20,000 个兄弟节点上的耗时(翻译成逐个数前面的兄弟)'), ('0 个', '默认命名空间的 Atom 文档上 //entry 能查到的节点数')],
    [('底层', '<p>parsel 的 <code>Selector</code> 用 lxml 解析并执行 XPath;<code>css()</code> 经 cssselect 翻译成 XPath 之后执行,所以 css 不比 xpath 快。</p>'),
     ('取文本', '<p><code>::text</code> 只取直接子文本;要所有后代文本写 <code>::text</code> 前加空格或用 <code>//text()</code>;要拼接成一个字符串用 <code>string()</code>。</p>'),
     ('坏 HTML', '<p>libxml2 的 HTML 解析器会补全、理顺标签,所以选择器几乎不会因为 HTML 写得烂而失败;<code>type="xml"</code> 同样是容错模式但修复结果不同。</p>'),
     ('命名空间', '<p>XML 带默认命名空间时普通 XPath 查不到元素,需要给前缀或 <code>remove_namespaces()</code>。</p>'),
     ('性能', '<p>解析很快(1 MB 约 16 ms),慢在选择器本身:类选择器翻译出来的 XPath 比 <code>@class</code> 等值判断慢数倍,<code>:nth-child(n)</code> 在大量兄弟上是平方级。解析结果缓存在 <code>response.selector</code> 里。</p>')],
    steps,
    [ENV_Y + '(cssselect 1.6.0)。除命名空间和耗时外,实验直接在虚拟环境里构造 Selector / HtmlResponse;耗时取 20 次中位数(解析取 5 次),文档是 20,000 个 li 的 1,077,815 字节 HTML',
     '没有验证:Selector 的 type="json"、jmespath 的使用(见后面的文章);xpath 的 EXSLT 正则扩展(re:test);真实网页(嵌套深、脚本多)上的解析耗时;lxml 以外的解析器;css 与 xpath 在小文档上的耗时差(这里只在 1 MB 文档上量过);编码问题(见响应编码那一篇)'],
    '选择器')
